insert into public.markets (slug, icon, sort, relevance, content) values ('artisans', 'wrench', 1, 5, '{"en":{"name":"Artisans","who":"Plumbers, electricians, carpenters, painters, locksmiths — skilled trades working for private clients and small businesses.","why":"Their work is excellent, but prospects check them online before calling — and often find nothing convincing.","problem":"Word of mouth is no longer enough, the business is poorly presented online, and requests get lost between calls, texts and social media.","angle":"Don’t sell “a small website”: sell the result — more trust, requests that arrive complete, and a business that looks as professional online as on site.","message":"Hello {{firstName}}, I came across {{company}}. Quick question: when someone hears about you and looks you up online, what do they find? I work with Studio ATS, which gives trades a professional presence that collects complete requests (job, place, timing) even while you’re on site. Worth 10 minutes? {{affiliateUrl}}","searches":["plombier [city]","électricien [city]","menuisier [city]","artisan peintre [city]"],"pains":["Word of mouth alone doesn’t fill the calendar","The business is poorly presented online","Prospects check the company online before calling","Requests get lost while working on site","No time to answer every message quickly","Dependence on social networks they don’t control"],"needs":["Look credible in 10 seconds","Receive requests with the right details","Not spend evenings on admin"],"outcomes":["More trust from people who don’t know them yet","A professional presence that matches the quality of their work","Requests centralised in one place","Available 24/7, even while on a job","Better conversion of visitors into real requests"],"discovery":["How do most of your new clients find you today?","What happens when someone looks you up online?","How many calls or messages do you miss while on a job?","Which jobs would you like more of?"],"avoid":"Never pitch it as “a small website” — talk about trust, complete requests and time saved."},"fr":{"name":"Artisans","who":"Plombiers, électriciens, menuisiers, peintres, serruriers — métiers du bâtiment et de l’entretien travaillant pour des particuliers et des petites entreprises.","why":"Leur travail est excellent, mais les prospects les vérifient en ligne avant d’appeler — et trouvent souvent peu de choses rassurantes.","problem":"Le bouche-à-oreille ne suffit plus, l’activité est mal présentée en ligne et les demandes se perdent entre appels, SMS et réseaux sociaux.","angle":"Ne vendez pas « un petit site internet » : vendez le résultat — plus de confiance, des demandes complètes et une entreprise aussi professionnelle en ligne que sur le chantier.","message":"Bonjour {{firstName}}, j’ai découvert {{company}}. Petite question : quand quelqu’un entend parler de vous et vous cherche en ligne, que trouve-t-il ? Je travaille avec Studio ATS, qui donne aux artisans une présence professionnelle qui recueille des demandes complètes (travaux, lieu, délai), même pendant que vous êtes sur un chantier. Ça vaut 10 minutes ? {{affiliateUrl}}","searches":["plombier [ville]","électricien [ville]","menuisier [ville]","artisan peintre [ville]"],"pains":["Le bouche-à-oreille seul ne remplit plus le planning","L’activité est mal présentée en ligne","Les prospects vérifient l’entreprise avant d’appeler","Des demandes se perdent pendant les chantiers","Peu de temps pour répondre vite à chaque message","Une dépendance à des réseaux sociaux qu’ils ne maîtrisent pas"],"needs":["Inspirer confiance en 10 secondes","Recevoir des demandes avec les bonnes informations","Ne pas passer ses soirées sur l’administratif"],"outcomes":["Davantage de confiance de la part de ceux qui ne les connaissent pas encore","Une présence professionnelle à la hauteur de leur travail","Des demandes centralisées au même endroit","Une disponibilité permanente, même en intervention","Une meilleure conversion des visiteurs en vraies demandes"],"discovery":["Comment la plupart de vos nouveaux clients vous trouvent-ils aujourd’hui ?","Que se passe-t-il quand quelqu’un vous cherche en ligne ?","Combien d’appels ou de messages manquez-vous pendant un chantier ?","Quels types de travaux aimeriez-vous faire davantage ?"],"avoid":"Ne le présentez jamais comme « un petit site » — parlez de confiance, de demandes complètes et de temps gagné."}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('construction', 'hardhat', 2, 4, '{"en":{"name":"Construction companies","who":"Builders, roofers, masons and general contractors handling larger projects for private and professional clients.","why":"Projects are large and clients compare several companies — credibility and a clear first request make the difference.","problem":"Quote requests arrive incomplete, site visits are wasted on projects that don’t fit, and past work is not shown anywhere.","angle":"Show finished projects and qualify every request (type, surface, budget, timing) before anyone drives to a site.","message":"Hello {{firstName}}, I saw {{company}}’s work. How many quote requests turn out to be out of scope once you’re on site? Studio ATS shows your best projects and asks the right questions before the visit. Shall I show you in 10 minutes?","searches":["entreprise de maçonnerie [city]","couvreur [city]","entreprise générale bâtiment [city]"],"pains":["Incomplete quote requests","Wasted site visits","Past projects not visible online","Hard to stand out when clients compare"],"outcomes":["Requests qualified before the visit","Credibility through real references","One place for every request"],"discovery":["How do you decide which quote requests deserve a visit?","Where can a prospect see your finished projects today?"],"avoid":"Don’t talk technology — talk about fewer wasted visits and better-prepared quotes."},"fr":{"name":"Entreprises du bâtiment","who":"Constructeurs, couvreurs, maçons et entreprises générales réalisant des chantiers importants pour particuliers et professionnels.","why":"Les projets sont importants et les clients comparent plusieurs entreprises — la crédibilité et une première demande claire font la différence.","problem":"Les demandes de devis arrivent incomplètes, des visites sont perdues sur des projets hors cible, et les réalisations ne sont montrées nulle part.","angle":"Montrez les chantiers réalisés et qualifiez chaque demande (type, surface, budget, délai) avant de vous déplacer.","message":"Bonjour {{firstName}}, j’ai vu les réalisations de {{company}}. Combien de demandes de devis se révèlent hors cible une fois sur place ? Studio ATS présente vos plus beaux chantiers et pose les bonnes questions avant la visite. Je vous montre en 10 minutes ?","searches":["entreprise de maçonnerie [ville]","couvreur [ville]","entreprise générale bâtiment [ville]"],"pains":["Des demandes de devis incomplètes","Des visites de chantier inutiles","Des réalisations invisibles en ligne","Difficile de se démarquer face à la concurrence"],"outcomes":["Des demandes qualifiées avant la visite","Une crédibilité appuyée sur de vraies références","Un seul endroit pour toutes les demandes"],"discovery":["Comment décidez-vous quelles demandes méritent une visite ?","Où un prospect peut-il voir vos chantiers terminés aujourd’hui ?"],"avoid":"Ne parlez pas technologie — parlez de visites inutiles évitées et de devis mieux préparés."}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('garages', 'car', 3, 4, '{"en":{"name":"Garages & auto services","who":"Independent garages, body shops, tyre and car-care specialists.","why":"Drivers compare garages online and want to know quickly if their job can be handled and when.","problem":"The phone rings during repairs, booking requests lack the vehicle and the issue, and the garage looks outdated online.","angle":"Let drivers describe their vehicle and need, and request a slot — without interrupting the workshop.","message":"Hello {{firstName}}, quick question for {{company}}: how do drivers book with you today — mostly by phone during repairs? Studio ATS lets them describe the vehicle and the job and request a slot online. Worth a look?","searches":["garage automobile [city]","carrosserie [city]","garage indépendant [city]"],"pains":["Phone interruptions during repairs","Requests without vehicle or issue details","An outdated online image"],"outcomes":["Complete requests (vehicle, issue, availability)","Fewer interruptions in the workshop","A modern, trustworthy presence"],"discovery":["How many calls do you take while working on a car?","What information is always missing when someone calls?"],"avoid":"Don’t promise more customers — talk about complete requests and fewer interruptions."},"fr":{"name":"Garages & services auto","who":"Garages indépendants, carrossiers, spécialistes pneus et entretien.","why":"Les conducteurs comparent les garages en ligne et veulent savoir vite si leur intervention est possible et quand.","problem":"Le téléphone sonne pendant les réparations, les demandes arrivent sans le véhicule ni la panne, et le garage paraît daté en ligne.","angle":"Laissez les conducteurs décrire leur véhicule et leur besoin, puis demander un créneau — sans interrompre l’atelier.","message":"Bonjour {{firstName}}, petite question pour {{company}} : comment vos clients prennent-ils rendez-vous aujourd’hui — surtout par téléphone pendant les réparations ? Studio ATS leur permet de décrire le véhicule et l’intervention et de demander un créneau en ligne. Ça vaut un coup d’œil ?","searches":["garage automobile [ville]","carrosserie [ville]","garage indépendant [ville]"],"pains":["Des interruptions téléphoniques pendant les réparations","Des demandes sans détails sur le véhicule ou la panne","Une image en ligne datée"],"outcomes":["Des demandes complètes (véhicule, panne, disponibilités)","Moins d’interruptions à l’atelier","Une présence moderne et rassurante"],"discovery":["Combien d’appels prenez-vous pendant une réparation ?","Quelle information manque toujours quand on vous appelle ?"],"avoid":"Ne promettez pas plus de clients — parlez de demandes complètes et de moins d’interruptions."}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('health-wellness', 'health', 4, 4, '{"en":{"name":"Health & wellness","who":"Independent practitioners in wellness and non-medical care: coaches, massage therapists, beauty and wellbeing studios.","why":"Clients choose on trust and need to understand the approach and the practical details before booking.","problem":"Questions repeat by message, the offer is unclear online, and booking requests arrive without context.","angle":"A reassuring space that explains the approach, answers the usual questions and collects clean appointment requests.","message":"Hello {{firstName}}, I discovered {{company}}. Do new clients often ask the same questions before booking? Studio ATS presents your approach clearly and collects appointment requests with the right context. Open to a short demo?","searches":["praticien bien-être [city]","institut de beauté [city]","coach [city]"],"pains":["The same questions answered again and again","An offer that is unclear online","Booking requests without context"],"outcomes":["A reassuring, clear presentation","Fewer repetitive questions","Structured appointment requests"],"discovery":["What do new clients ask most before booking?","How do they book with you today?"],"avoid":"Regulated medical professions have strict communication rules — do not make health claims; stick to organisation and presentation."},"fr":{"name":"Santé & bien-être","who":"Praticiens indépendants du bien-être et des soins non médicaux : coachs, masseurs, instituts de beauté et de bien-être.","why":"Les clients choisissent sur la confiance et veulent comprendre l’approche et les modalités avant de réserver.","problem":"Les questions se répètent par message, l’offre est floue en ligne et les demandes de rendez-vous arrivent sans contexte.","angle":"Un espace rassurant qui explique l’approche, répond aux questions habituelles et recueille des demandes de rendez-vous claires.","message":"Bonjour {{firstName}}, j’ai découvert {{company}}. Vos nouveaux clients posent-ils souvent les mêmes questions avant de réserver ? Studio ATS présente clairement votre approche et recueille des demandes de rendez-vous avec le bon contexte. Partant pour une courte démo ?","searches":["praticien bien-être [ville]","institut de beauté [ville]","coach [ville]"],"pains":["Toujours les mêmes questions","Une offre peu claire en ligne","Des demandes de rendez-vous sans contexte"],"outcomes":["Une présentation claire et rassurante","Moins de questions répétitives","Des demandes de rendez-vous structurées"],"discovery":["Que vous demandent le plus souvent les nouveaux clients avant de réserver ?","Comment réservent-ils chez vous aujourd’hui ?"],"avoid":"Les professions médicales réglementées ont des règles de communication strictes — aucune allégation de santé ; restez sur l’organisation et la présentation."}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('independents', 'user', 5, 3, '{"en":{"name":"Freelancers & independents","who":"Freelancers and solo professionals selling their expertise: designers, developers, trainers, translators.","why":"Alone, they need to look established and qualify requests without spending hours in back-and-forth.","problem":"Requests arrive by email and LinkedIn with no budget or timing, and the offer is hard to understand from a profile page.","angle":"Look like an established studio and receive requests that already contain scope, timing and budget.","message":"Hi {{firstName}}, I follow your work. When a new client contacts you, do you usually get a clear brief? Studio ATS gives independents a professional space that presents the offer and qualifies each request. Want to see it?","searches":["freelance [specialty] [city]","consultant indépendant [specialty]","LinkedIn: freelance [specialty]"],"pains":["Vague requests with no budget","Hours of back-and-forth before a quote","An offer that is hard to grasp online"],"outcomes":["An established, professional image","Qualified briefs","More time for billable work"],"discovery":["What does a typical first request look like?","How long does it take you to qualify a new project?"],"avoid":"Don’t oversell automation — focus on credibility and better briefs."},"fr":{"name":"Indépendants & freelances","who":"Freelances et professionnels seuls vendant leur expertise : designers, développeurs, formateurs, traducteurs.","why":"Seuls, ils doivent paraître établis et qualifier les demandes sans passer des heures en allers-retours.","problem":"Les demandes arrivent par email et LinkedIn sans budget ni délai, et l’offre est difficile à comprendre depuis un simple profil.","angle":"Paraître comme un studio établi et recevoir des demandes qui précisent déjà périmètre, délai et budget.","message":"Bonjour {{firstName}}, je suis votre travail. Quand un nouveau client vous contacte, avez-vous en général un brief clair ? Studio ATS donne aux indépendants un espace professionnel qui présente l’offre et qualifie chaque demande. Envie de voir ?","searches":["freelance [spécialité] [ville]","consultant indépendant [spécialité]","LinkedIn : freelance [spécialité]"],"pains":["Des demandes vagues sans budget","Des heures d’allers-retours avant un devis","Une offre difficile à saisir en ligne"],"outcomes":["Une image établie et professionnelle","Des briefs qualifiés","Plus de temps pour le travail facturable"],"discovery":["À quoi ressemble une première demande typique ?","Combien de temps vous faut-il pour qualifier un nouveau projet ?"],"avoid":"Ne survendez pas l’automatisation — insistez sur la crédibilité et de meilleurs briefs."}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('agencies', 'megaphone', 6, 3, '{"en":{"name":"Agencies","who":"Small creative, communication and marketing agencies.","why":"They sell to demanding clients and need a showcase and an intake process that match their positioning.","problem":"The agency’s own site is often the last priority; new business requests are mixed with everything else.","angle":"A new-business engine the agency doesn’t have to build or maintain itself.","message":"Hi {{firstName}}, agencies often build great things for clients and have no time for their own new-business flow. How do prospects brief {{company}} today? Studio ATS handles showcase + qualified intake for you. Worth 10 minutes?","searches":["agence de communication [city]","agence créative [city]","agence marketing [city]"],"pains":["Their own site is never a priority","New-business requests mixed with daily email","Briefs arrive without budget"],"outcomes":["A showcase that reflects their level","A structured new-business intake","Nothing to build or maintain internally"],"discovery":["Who handles new-business requests at the agency?","When did you last update your own site?"],"avoid":"Agencies can build websites — sell the time saved and the done-for-you intake, not the site."},"fr":{"name":"Agences","who":"Petites agences créatives, de communication et de marketing.","why":"Elles vendent à des clients exigeants et ont besoin d’une vitrine et d’une prise de brief à la hauteur de leur positionnement.","problem":"Le site de l’agence passe toujours en dernier ; les demandes de nouveaux clients se mélangent au reste.","angle":"Un moteur de new business que l’agence n’a ni à construire ni à maintenir.","message":"Bonjour {{firstName}}, les agences construisent souvent de belles choses pour leurs clients et n’ont pas le temps pour leur propre prospection. Comment les prospects briefent-ils {{company}} aujourd’hui ? Studio ATS gère vitrine et prise de brief qualifiée pour vous. Ça vaut 10 minutes ?","searches":["agence de communication [ville]","agence créative [ville]","agence marketing [ville]"],"pains":["Leur propre site n’est jamais prioritaire","Des demandes mélangées aux emails quotidiens","Des briefs sans budget"],"outcomes":["Une vitrine à la hauteur de leur niveau","Une prise de brief structurée","Rien à construire ni à maintenir en interne"],"discovery":["Qui gère les demandes de nouveaux clients à l’agence ?","Quand avez-vous mis à jour votre propre site pour la dernière fois ?"],"avoid":"Une agence sait faire des sites — vendez le temps gagné et la prise de brief clé en main, pas le site."}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('service-providers', 'handshake', 7, 4, '{"en":{"name":"Service providers","who":"Cleaning, maintenance, moving, home-help and other service companies working on quotes.","why":"Every quote requires information; incomplete requests cost time and slow the answer.","problem":"Requests arrive without surface, address or dates, and the company answers too late to win the job.","angle":"Collect everything needed for a quote in the first request, and answer faster than competitors.","message":"Hello {{firstName}}, how do quote requests reach {{company}} today, and what’s usually missing? Studio ATS collects the details you need for a quote in the first request. Shall I show you?","searches":["entreprise de nettoyage [city]","déménagement [city]","entreprise de services [city]"],"pains":["Incomplete quote requests","Slow answers that lose jobs","Too much time spent on the phone"],"outcomes":["Quote-ready requests","Faster answers","A clear, professional presentation of services"],"discovery":["What information do you need for a quote?","How quickly can you usually answer a request?"],"avoid":"Don’t promise to win more quotes — talk about faster, better-prepared answers."},"fr":{"name":"Prestataires de services","who":"Nettoyage, maintenance, déménagement, aide à domicile et autres entreprises de services travaillant sur devis.","why":"Chaque devis demande des informations ; les demandes incomplètes coûtent du temps et ralentissent la réponse.","problem":"Les demandes arrivent sans surface, adresse ni dates, et l’entreprise répond trop tard pour décrocher le travail.","angle":"Recueillir tout ce qu’il faut pour un devis dès la première demande, et répondre plus vite que la concurrence.","message":"Bonjour {{firstName}}, comment les demandes de devis arrivent-elles chez {{company}} aujourd’hui, et que manque-t-il souvent ? Studio ATS recueille dès la première demande les informations nécessaires au devis. Je vous montre ?","searches":["entreprise de nettoyage [ville]","déménagement [ville]","entreprise de services [ville]"],"pains":["Des demandes de devis incomplètes","Des réponses lentes qui font perdre des chantiers","Trop de temps au téléphone"],"outcomes":["Des demandes prêtes pour le devis","Des réponses plus rapides","Une présentation claire et professionnelle des services"],"discovery":["De quelles informations avez-vous besoin pour un devis ?","En combien de temps répondez-vous en général à une demande ?"],"avoid":"Ne promettez pas de gagner plus de devis — parlez de réponses plus rapides et mieux préparées."}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('local-businesses', 'store', 8, 3, '{"en":{"name":"Local businesses","who":"Shops, studios, restaurants with private events, and other local businesses taking bookings or requests.","why":"Locals search online first; a clear presence and an easy request path decide who gets the call.","problem":"Information is scattered across social profiles and directories, and requests arrive through too many channels.","angle":"One clear place that presents the business and turns local searches into structured requests.","message":"Hello {{firstName}}, when people nearby look for {{company}} online, where do they end up? Studio ATS gives local businesses one clear place to present the offer and receive requests. Worth a quick look?","searches":["[activity] [city]","commerce [city]","réservation événement privé [city]"],"pains":["Information scattered across profiles","Requests through too many channels","Little control over their online image"],"outcomes":["One clear, controlled presence","Requests in one place","An easy path from search to request"],"discovery":["Where do new customers find you?","Which requests would you like to receive more easily?"],"avoid":"Don’t compete with free directories — explain what a controlled, professional space adds."},"fr":{"name":"Entreprises locales","who":"Commerces, studios, restaurants avec événements privés et autres entreprises locales recevant réservations ou demandes.","why":"Les habitants cherchent d’abord en ligne ; une présence claire et une demande facile décident de qui reçoit l’appel.","problem":"Les informations sont éparpillées entre profils sociaux et annuaires, et les demandes arrivent par trop de canaux.","angle":"Un seul endroit clair qui présente l’activité et transforme les recherches locales en demandes structurées.","message":"Bonjour {{firstName}}, quand les gens du coin cherchent {{company}} en ligne, où arrivent-ils ? Studio ATS donne aux entreprises locales un endroit clair pour présenter l’offre et recevoir les demandes. Ça vaut un coup d’œil ?","searches":["[activité] [ville]","commerce [ville]","réservation événement privé [ville]"],"pains":["Des informations éparpillées","Des demandes par trop de canaux","Peu de maîtrise de leur image en ligne"],"outcomes":["Une présence claire et maîtrisée","Des demandes centralisées","Un chemin simple de la recherche à la demande"],"discovery":["Où vos nouveaux clients vous trouvent-ils ?","Quelles demandes aimeriez-vous recevoir plus facilement ?"],"avoid":"Ne vous battez pas contre les annuaires gratuits — expliquez ce qu’apporte un espace professionnel maîtrisé."}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('photographers', 'camera', 1, 3, '{"en":{"name":"Photographers","who":"Wedding, portrait, corporate and architecture photographers with a premium offer.","why":"Their portfolio is their shop window — Studio ATS turns it into a booking engine.","problem":"Enquiries arrive through Instagram DMs and a basic form, without date, budget or project type.","angle":"Stop answering vague DMs — receive qualified requests with the date and budget already filled in.","message":"Hi [First name], I love your work on [project]. Quick question: how do most of your clients contact you today? I work with Studio ATS, which turns a photographer’s portfolio into a space that qualifies requests (date, budget, type of shoot) and books calls automatically. Open to a 10-minute look?","searches":["wedding photographer [city]","portrait photographer [city]","#weddingphotographer [city]"]},"fr":{"name":"Photographes","who":"Photographes de mariage, portrait, entreprise et architecture avec une offre premium.","why":"Leur portfolio est leur vitrine — Studio ATS en fait un outil de réservation.","problem":"Les demandes arrivent en DM Instagram et via un formulaire basique, sans date, budget ni type de projet.","angle":"Arrêtez de répondre à des DM vagues — recevez des demandes qualifiées avec date et budget.","message":"Bonjour [Prénom], j’adore votre travail sur [projet]. Petite question : comment la plupart de vos clients vous contactent-ils aujourd’hui ? Je travaille avec Studio ATS, qui transforme le portfolio d’un photographe en espace qui qualifie les demandes (date, budget, type de séance) et programme les appels automatiquement. Ouvert à un aperçu de 10 minutes ?","searches":["photographe mariage [ville]","photographe portrait [ville]","#photographemariage [ville]"]}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('wedding-planners', 'rings', 2, 3, '{"en":{"name":"Wedding planners","who":"Independent planners and agencies organising premium weddings.","why":"Each wedding is a high-value project; every missed request is a lost season slot.","problem":"Couples send the same questions again and again; qualification happens over long email threads.","angle":"Let couples present their project before the first call — you only talk to the right ones.","message":"Hello [First name], your [venue / style] weddings are beautiful. I’m reaching out because Studio ATS helps planners receive couples’ requests already qualified — date, guests, budget, style — and book the discovery call automatically. Would it be useful to see how it works?","searches":["wedding planner [city]","organisatrice mariage [city]","destination wedding planner [region]"]},"fr":{"name":"Wedding planners","who":"Wedding planners indépendants et agences organisant des mariages haut de gamme.","why":"Chaque mariage est un projet à forte valeur ; chaque demande perdue est une date perdue.","problem":"Les couples posent toujours les mêmes questions ; la qualification se fait par longs échanges d’emails.","angle":"Laissez les couples présenter leur projet avant le premier appel — vous ne parlez qu’aux bons.","message":"Bonjour [Prénom], vos mariages [lieu / style] sont superbes. Je vous contacte car Studio ATS aide les wedding planners à recevoir des demandes déjà qualifiées — date, invités, budget, style — et à programmer l’appel découverte automatiquement. Ça vous intéresserait de voir comment ça marche ?","searches":["wedding planner [ville]","organisatrice de mariage [ville]","mariage clé en main [région]"]}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('videographers', 'video', 3, 3, '{"en":{"name":"Videographers","who":"Wedding, corporate and brand-content videographers and small production studios.","why":"Video projects are expensive — prospects need to see work and understand the process before calling.","problem":"Showreels live on YouTube/Vimeo, requests come in without scope, quoting takes hours.","angle":"Your showreel + a guided brief = requests you can quote immediately.","message":"Hi [First name], great reel on [project]. When a brand contacts you, do you usually get a clear brief? Studio ATS turns your portfolio into a space where prospects describe format, deadline and budget before the call. Worth a quick look?","searches":["videographer [city]","video production company [city]","wedding videographer [region]"]},"fr":{"name":"Vidéastes","who":"Vidéastes mariage, corporate, contenu de marque et petits studios de production.","why":"Un projet vidéo coûte cher — le prospect doit voir le travail et comprendre le process avant d’appeler.","problem":"Les showreels sont sur YouTube/Vimeo, les demandes arrivent sans cadrage, chiffrer prend des heures.","angle":"Votre showreel + un brief guidé = des demandes chiffrables immédiatement.","message":"Bonjour [Prénom], super réalisation sur [projet]. Quand une marque vous contacte, avez-vous en général un brief clair ? Studio ATS transforme votre portfolio en espace où le prospect précise format, délai et budget avant l’appel. Ça vaut un coup d’œil ?","searches":["vidéaste [ville]","société de production vidéo [ville]","vidéaste mariage [région]"]}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('architects', 'ruler', 4, 3, '{"en":{"name":"Architects","who":"Architecture practices working with private clients and small businesses.","why":"Projects have long cycles and high value — first impressions and qualification matter.","problem":"Most requests are too early, too small or out of scope, and take time to filter.","angle":"Present your references like a monograph and filter projects by scope before the first meeting.","message":"Hello [First name], I came across your project [name]. Many practices tell me they spend time on requests that aren’t a fit. Studio ATS presents your references and qualifies each project (type, surface, budget, timing) before the first meeting. Open to a short demo?","searches":["architect [city]","architecte DPLG [city]","residential architect [region]"]},"fr":{"name":"Architectes","who":"Cabinets d’architecture travaillant avec des particuliers et des petites entreprises.","why":"Des cycles longs, une forte valeur — la première impression et la qualification comptent.","problem":"Beaucoup de demandes arrivent trop tôt, sont trop petites ou hors périmètre, et prennent du temps à trier.","angle":"Présentez vos références comme une monographie et filtrez les projets avant le premier rendez-vous.","message":"Bonjour [Prénom], j’ai découvert votre projet [nom]. Beaucoup de cabinets me disent passer du temps sur des demandes qui ne leur correspondent pas. Studio ATS présente vos références et qualifie chaque projet (type, surface, budget, délai) avant le premier rendez-vous. Partant pour une courte démo ?","searches":["architecte [ville]","architecte maison individuelle [ville]","architecte rénovation [région]"]}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('interior-designers', 'sofa', 5, 3, '{"en":{"name":"Interior designers","who":"Interior designers and decorators working on premium residential or hospitality projects.","why":"Their work is visual and their clients buy on trust and taste.","problem":"Beautiful Instagram, but no structured way to capture and qualify project requests.","angle":"Turn your Instagram audience into structured project requests.","message":"Hi [First name], your [project] is stunning. Do your Instagram followers have an easy way to request a project with you? Studio ATS gives designers a premium portfolio that captures and qualifies requests — room, surface, budget, timing. Happy to show you in 10 minutes.","searches":["interior designer [city]","décoratrice d’intérieur [city]","#interiordesign [city]"]},"fr":{"name":"Architectes d’intérieur","who":"Architectes d’intérieur et décorateurs sur des projets résidentiels ou hôteliers haut de gamme.","why":"Leur travail est visuel et leurs clients achètent sur la confiance et le goût.","problem":"Un bel Instagram, mais aucun moyen structuré de capter et qualifier les demandes.","angle":"Transformez votre audience Instagram en demandes de projets structurées.","message":"Bonjour [Prénom], votre projet [nom] est magnifique. Vos abonnés Instagram ont-ils un moyen simple de vous demander un projet ? Studio ATS offre aux architectes d’intérieur un portfolio premium qui capte et qualifie les demandes — pièce, surface, budget, délai. Je vous montre en 10 minutes ?","searches":["architecte d’intérieur [ville]","décoratrice d’intérieur [ville]","#decorationinterieur [ville]"]}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('renovation', 'hammer', 6, 3, '{"en":{"name":"Premium renovation companies","who":"Renovation companies focused on high-end homes and complete refurbishments.","why":"Large tickets, many unqualified quote requests.","problem":"Teams travel for site visits that don’t lead anywhere.","angle":"Qualify every project before the site visit — surface, budget, timing and photos upfront.","message":"Hello [First name], I saw your renovation in [place]. How many site visits a month end up going nowhere? Studio ATS shows your best projects and asks the right questions (surface, budget, timing, photos) before you move. Interested in seeing it?","searches":["rénovation haut de gamme [city]","renovation company [city]","entreprise rénovation appartement [city]"]},"fr":{"name":"Rénovation haut de gamme","who":"Entreprises de rénovation spécialisées dans les biens haut de gamme et les rénovations complètes.","why":"Des paniers élevés, beaucoup de demandes de devis non qualifiées.","problem":"Les équipes se déplacent pour des visites qui n’aboutissent pas.","angle":"Qualifiez chaque projet avant la visite — surface, budget, délai et photos en amont.","message":"Bonjour [Prénom], j’ai vu votre rénovation à [lieu]. Combien de visites par mois ne mènent à rien ? Studio ATS présente vos plus beaux chantiers et pose les bonnes questions (surface, budget, délai, photos) avant que vous vous déplaciez. Ça vous intéresse ?","searches":["rénovation haut de gamme [ville]","entreprise rénovation appartement [ville]","rénovation maison ancienne [région]"]}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('kitchen-designers', 'kitchen', 7, 3, '{"en":{"name":"Kitchen designers","who":"Kitchen showrooms and independent kitchen designers.","why":"High-value projects that start online and close in the showroom.","problem":"Showroom appointments are booked by phone, with little information about the project.","angle":"Get the showroom appointment booked with the project already described.","message":"Hi [First name], beautiful kitchens on your site. How do prospects book a showroom visit today? Studio ATS lets them describe their project and request an appointment online, so each visit is prepared. 10 minutes to show you?","searches":["cuisiniste [city]","kitchen showroom [city]","custom kitchen designer [region]"]},"fr":{"name":"Cuisinistes","who":"Showrooms de cuisine et concepteurs de cuisines indépendants.","why":"Des projets à forte valeur qui commencent en ligne et se concluent en showroom.","problem":"Les rendez-vous showroom sont pris par téléphone, avec peu d’informations sur le projet.","angle":"Obtenez le rendez-vous showroom avec le projet déjà décrit.","message":"Bonjour [Prénom], très belles cuisines sur votre site. Comment vos prospects réservent-ils une visite showroom aujourd’hui ? Studio ATS leur permet de décrire leur projet et de demander un rendez-vous en ligne : chaque visite est préparée. 10 minutes pour vous montrer ?","searches":["cuisiniste [ville]","cuisine sur mesure [ville]","showroom cuisine [région]"]}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('landscapers', 'leaf', 8, 3, '{"en":{"name":"Landscapers","who":"Landscape designers and garden-creation companies.","why":"Seasonal demand — capturing and qualifying requests early matters.","problem":"Requests peak in spring and many are too small or outside the service area.","angle":"Filter by area, surface and budget automatically, and fill your season with the right projects.","message":"Hello [First name], lovely garden in [place]. When spring requests arrive, how do you sort the good projects? Studio ATS qualifies each request (area, surface, budget) and books the visit. Want to see it?","searches":["paysagiste [city]","landscape designer [city]","création jardin [region]"]},"fr":{"name":"Paysagistes","who":"Paysagistes concepteurs et entreprises de création de jardins.","why":"Demande saisonnière — capter et qualifier tôt les demandes est clé.","problem":"Les demandes explosent au printemps et beaucoup sont trop petites ou hors zone.","angle":"Filtrez automatiquement par zone, surface et budget et remplissez votre saison avec les bons projets.","message":"Bonjour [Prénom], très beau jardin à [lieu]. Quand les demandes du printemps arrivent, comment triez-vous les bons projets ? Studio ATS qualifie chaque demande (zone, surface, budget) et programme la visite. Envie de voir ?","searches":["paysagiste [ville]","création jardin [ville]","architecte paysagiste [région]"]}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('pool-installers', 'waves', 9, 3, '{"en":{"name":"Pool installers","who":"Pool builders and installers for private homes.","why":"High-ticket projects with a long decision process.","problem":"Many quote requests, few serious projects, and no automatic follow-up.","angle":"Automatic follow-ups keep your quote top of mind during a long decision.","message":"Hi [First name], I saw your pool projects in [region]. How do you follow up quotes while clients decide? Studio ATS qualifies requests and sends automatic follow-ups so good projects don’t go cold. Shall I show you?","searches":["pisciniste [city]","pool builder [region]","construction piscine [region]"]},"fr":{"name":"Piscinistes","who":"Constructeurs et installateurs de piscines pour particuliers.","why":"Des projets à fort panier avec une décision longue.","problem":"Beaucoup de demandes de devis, peu de projets sérieux, et aucune relance automatique.","angle":"Les relances automatiques gardent votre devis en tête pendant une longue décision.","message":"Bonjour [Prénom], j’ai vu vos réalisations en [région]. Comment relancez-vous vos devis pendant que le client réfléchit ? Studio ATS qualifie les demandes et envoie des relances automatiques pour que les bons projets ne refroidissent pas. Je vous montre ?","searches":["pisciniste [ville]","construction piscine [région]","piscine coque [région]"]}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('b2b-consultants', 'briefcase', 10, 3, '{"en":{"name":"B2B consultants","who":"Independent consultants and boutique firms selling high-value engagements.","why":"Each engagement is significant; credibility and qualification drive the sale.","problem":"Lead generation relies on LinkedIn and referrals, with no structured intake.","angle":"Convert your LinkedIn visibility into qualified discovery calls.","message":"Hello [First name], I follow your posts on [topic]. When someone is interested, where do you send them? Studio ATS gives consultants a credible space that presents case studies, qualifies needs and books discovery calls. Worth 10 minutes?","searches":["consultant [specialty] [city]","cabinet de conseil [specialty]","LinkedIn: consultant indépendant [specialty]"]},"fr":{"name":"Consultants B2B","who":"Consultants indépendants et petits cabinets vendant des missions à forte valeur.","why":"Chaque mission compte ; crédibilité et qualification font la vente.","problem":"La prospection repose sur LinkedIn et le bouche-à-oreille, sans prise de contact structurée.","angle":"Transformez votre visibilité LinkedIn en appels découverte qualifiés.","message":"Bonjour [Prénom], je suis vos publications sur [sujet]. Quand quelqu’un est intéressé, où l’envoyez-vous ? Studio ATS donne aux consultants un espace crédible qui présente les cas clients, qualifie le besoin et programme l’appel découverte. Ça vaut 10 minutes ?","searches":["consultant [spécialité] [ville]","cabinet de conseil [spécialité]","LinkedIn : consultant indépendant [spécialité]"]}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('recruitment', 'users', 11, 3, '{"en":{"name":"Recruitment firms","who":"Boutique recruitment and executive-search firms.","why":"Winning a new client account has high value; trust is built before the first call.","problem":"Client and candidate requests mix together; client acquisition is manual.","angle":"Separate client and candidate journeys and qualify hiring needs automatically.","message":"Hi [First name], I noticed your firm specialises in [sector]. How do new client companies contact you today? Studio ATS separates client and candidate requests and qualifies hiring needs before the call. Open to a quick look?","searches":["cabinet de recrutement [sector] [city]","executive search [city]","recruitment agency [niche]"]},"fr":{"name":"Cabinets de recrutement","who":"Cabinets de recrutement spécialisés et chasseurs de têtes.","why":"Gagner un nouveau client a une forte valeur ; la confiance se construit avant l’appel.","problem":"Les demandes clients et candidats se mélangent ; l’acquisition client est manuelle.","angle":"Séparez les parcours clients et candidats et qualifiez les besoins de recrutement automatiquement.","message":"Bonjour [Prénom], votre cabinet est spécialisé en [secteur]. Comment les entreprises clientes vous contactent-elles aujourd’hui ? Studio ATS sépare les demandes clients et candidats et qualifie le besoin avant l’appel. Ouvert à un rapide aperçu ?","searches":["cabinet de recrutement [secteur] [ville]","chasseur de têtes [ville]","recrutement [niche]"]}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.markets (slug, icon, sort, relevance, content) values ('event-professionals', 'sparkles', 12, 3, '{"en":{"name":"Premium event professionals","who":"Caterers, venues, event agencies, florists and decorators working on premium events.","why":"Each event is a high-value booking with a date that can only be sold once.","problem":"Availability, guest count and budget are exchanged over many messages.","angle":"Capture date, guest count and budget in the first request — answer only the right events.","message":"Hello [First name], your [event] setup was superb. How do clients check availability with you today? Studio ATS captures date, guests and budget in the first request and books the call. Want to see it?","searches":["traiteur événementiel [city]","lieu de réception [city]","event agency [city]"]},"fr":{"name":"Événementiel premium","who":"Traiteurs, lieux de réception, agences événementielles, fleuristes et décorateurs haut de gamme.","why":"Chaque événement est une réservation à forte valeur sur une date qu’on ne vend qu’une fois.","problem":"Disponibilité, nombre d’invités et budget s’échangent en de nombreux messages.","angle":"Captez date, invités et budget dès la première demande — ne répondez qu’aux bons événements.","message":"Bonjour [Prénom], votre mise en place pour [événement] était superbe. Comment vos clients vérifient-ils vos disponibilités aujourd’hui ? Studio ATS capte date, invités et budget dès la première demande et programme l’appel. Envie de voir ?","searches":["traiteur événementiel [ville]","lieu de réception [ville]","agence événementielle [ville]"]}}'::jsonb) on conflict (slug) do update set icon = excluded.icon, sort = excluded.sort, relevance = excluded.relevance, content = excluded.content;
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'email', 'en', 'First contact — portfolio businesses', 'Subject: [Company] — turning visitors into booked calls
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'email', 'en', 'Follow-up after 3 days', 'Subject: Re: [Company] — turning visitors into booked calls
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'whatsapp', 'en', 'Short intro', 'Hi [First name] 👋 I saw your work on [project] — really nice. I work with Studio ATS: it turns your portfolio into a space that qualifies requests and books calls automatically. Can I send you a 2-minute overview?', 2 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'whatsapp', 'en', 'After a call', 'Thanks for the call, [First name]! Here’s the Studio ATS page we discussed: [your link]. Let me know if you have any questions.', 3 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'linkedin', 'en', 'Connection note', 'Hi [First name], I help [profession] turn their online visibility into qualified appointments. Would love to connect.', 4 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'linkedin', 'en', 'Message after connecting', 'Thanks for connecting, [First name]. I noticed [Company] works on [type of project]. How do new clients usually reach you? I work with Studio ATS, which qualifies requests and books discovery calls automatically. Happy to share a short overview if useful: [your link]', 5 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'instagram', 'en', 'DM — portfolio creators', 'Hi! Your feed is beautiful 🙌 Quick question: when someone wants to book you, do they just DM? Studio ATS turns your portfolio into a booking space that asks date, budget and project type upfront. Want me to send the link?', 6 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'cold_call', 'en', 'Cold call script', '1. Opening — "Hi [First name], it’s [Your name]. I’ll be brief: I help [profession] turn website visitors into qualified appointments. Do you have 30 seconds?"
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'en', '“I already have a website.”', 'That’s great — Studio ATS isn’t about replacing a nice site. The question is what happens after the visit: are requests qualified? Are follow-ups automatic? Do you know which sources bring real clients? The website is one component; Studio ATS is the whole path to the appointment.', 8 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'en', '“It’s too expensive.”', 'It’s a fair question. How much is one new client worth to you? Studio ATS is €6,000 a year, everything included. For a professional whose clients have high value, the question is whether it helps convert the requests you already get. [Avoid promising results — let them do their own math.]', 9 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'en', '“I only work with Instagram.”', 'Instagram is excellent for being discovered. Studio ATS is where that attention turns into a structured request — with date, budget and project details — instead of another DM to chase. It complements Instagram; it doesn’t replace it.', 10 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'en', '“I don’t need automation.”', 'Understood. Automation here just means the confirmation email, the reminder and the follow-up go out on time — the things that get forgotten on busy weeks. You stay in control of every conversation.', 11 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'en', '“I need to think about it.”', 'Of course. To help you think it through: what would need to be true for this to be worth it for you? I’ll send you the overview [your link] and check back on [day] — does that work?', 12 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'email', 'fr', 'Premier contact — métiers à portfolio', 'Objet : [Entreprise] — transformer vos visiteurs en rendez-vous
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'email', 'fr', 'Relance à 3 jours', 'Objet : Re : [Entreprise] — transformer vos visiteurs en rendez-vous
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'whatsapp', 'fr', 'Intro courte', 'Bonjour [Prénom] 👋 J’ai vu votre travail sur [projet], très beau. Je travaille avec Studio ATS : il transforme votre portfolio en espace qui qualifie les demandes et programme les appels automatiquement. Je vous envoie une présentation de 2 minutes ?', 15 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'linkedin', 'fr', 'Note d’invitation', 'Bonjour [Prénom], j’aide les [métier] à transformer leur visibilité en ligne en rendez-vous qualifiés. Ravi d’échanger.', 16 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'instagram', 'fr', 'DM — créateurs à portfolio', 'Bonjour ! Votre feed est superbe 🙌 Petite question : quand quelqu’un veut vous réserver, il vous écrit en DM ? Studio ATS transforme votre portfolio en espace de réservation qui demande date, budget et type de projet. Je vous envoie le lien ?', 17 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'cold_call', 'fr', 'Script d’appel', '1. Accroche — « Bonjour [Prénom], [Votre nom]. Je serai bref : j’aide les [métier] à transformer les visiteurs de leur site en rendez-vous qualifiés. Vous avez 30 secondes ? »
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'fr', '« J’ai déjà un site. »', 'Très bien — Studio ATS ne remplace pas un beau site. La question, c’est ce qui se passe après la visite : les demandes sont-elles qualifiées ? Les relances automatiques ? Savez-vous quelles sources amènent de vrais clients ? Le site est une composante ; Studio ATS, c’est tout le chemin jusqu’au rendez-vous.', 19 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'fr', '« C’est trop cher. »', 'C’est une bonne question. Combien vaut un nouveau client pour vous ? Studio ATS coûte 6 000 € par an, tout compris. Pour un professionnel dont les clients ont une forte valeur, la question est de savoir s’il aide à convertir les demandes que vous recevez déjà. [Ne promettez pas de résultat — laissez le prospect faire son propre calcul.]', 20 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'fr', '« Je travaille uniquement avec Instagram. »', 'Instagram est excellent pour être découvert. Studio ATS est l’endroit où cette attention devient une demande structurée — avec date, budget et détails — au lieu d’un énième DM à relancer. Il complète Instagram, il ne le remplace pas.', 21 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'fr', '« Je n’ai pas besoin d’automatisation. »', 'Je comprends. Ici, l’automatisation signifie simplement que l’email de confirmation, le rappel et la relance partent à temps — ce qu’on oublie les semaines chargées. Vous gardez la main sur chaque conversation.', 22 from public.products where slug = 'studio';
insert into public.sales_assets (product_id, type, locale, title, body, sort) select id, 'objection', 'fr', '« Je dois réfléchir. »', 'Bien sûr. Pour vous aider : qu’est-ce qui devrait être vrai pour que ça en vaille la peine pour vous ? Je vous envoie la présentation [votre lien] et je reviens vers vous [jour] — ça vous va ?', 23 from public.products where slug = 'studio';
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'page_template', 'studio-default', 'en', 1, 'active', p.id, null, null, null, 'Studio ATS — standard sales page', 'Default structure for every affiliate sales page.', '{"ctaModes":["buy","lead","call","quote","question"],"defaultCta":"lead","sections":["hero","problem","solution","value","how","benefits","included","who","faq","offer","cta"],"heroTitle":"Turn your traffic into opportunities.","heroSubtitle":"An online commercial studio for professionals whose every new client has real value. Present your work, qualify requests and book appointments — in one place.","problemTitle":"Great work. Lost requests.","problemBody":"Enquiries arrive through a contact form, social media, messages and email. Nobody knows which ones are serious, follow-ups are forgotten, and good prospects go cold.","solutionTitle":"More than a website.","solutionBody":"The site is only one part. Studio ATS is the whole path from first visit to booked appointment — designed, set up and maintained for you.","valueTitle":"What you actually get","valueItems":["A presence that inspires trust at first glance","Requests that arrive with the right information","Every contact and request in one place","Follow-ups that go out on time"],"howTitle":"How it works","howSteps":[{"title":"Request","body":"Tell us about your business in a short form."},{"title":"Call","body":"We qualify your needs together."},{"title":"Build","body":"We design and configure your Studio ATS."},{"title":"Launch","body":"You start receiving structured requests."}],"benefitsTitle":"Why it matters for your business","benefits":[{"title":"Trust","body":"Prospects check you online before calling. Make that first impression count."},{"title":"Time","body":"Know budget, timing and project type before you pick up the phone."},{"title":"Nothing to manage","body":"Built, hosted and maintained by the Studio ATS team."}],"includedTitle":"What’s included","whoTitle":"Who it’s for","whoBody":"Professionals and companies whose clients are worth a lot, with a visual or premium offer and inbound requests to convert.","faqTitle":"Questions you may have","offerTitle":"One plan. Everything included.","offerNote":"Price excl. VAT where applicable. Final terms in the contract.","ctaTitle":"Ready to talk about your business?","ctaBody":"Leave your details — no commitment. We’ll get back to you to understand your needs."}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'page_template', 'studio-default', 'fr', 1, 'active', p.id, null, null, null, 'Studio ATS — page commerciale standard', 'Structure par défaut de toutes les pages commerciales affiliées.', '{"ctaModes":["buy","lead","call","quote","question"],"defaultCta":"lead","sections":["hero","problem","solution","value","how","benefits","included","who","faq","offer","cta"],"heroTitle":"Transformez votre trafic en opportunités.","heroSubtitle":"Un studio commercial en ligne pour les professionnels dont chaque nouveau client compte. Présentez votre travail, qualifiez les demandes et obtenez des rendez-vous — au même endroit.","problemTitle":"Un beau travail. Des demandes perdues.","problemBody":"Les demandes arrivent par formulaire, réseaux sociaux, messages et email. Personne ne sait lesquelles sont sérieuses, les relances sont oubliées et les bons prospects refroidissent.","solutionTitle":"Bien plus qu’un site.","solutionBody":"Le site n’est qu’une partie. Studio ATS, c’est tout le parcours, de la première visite au rendez-vous — conçu, mis en place et maintenu pour vous.","valueTitle":"Ce que vous obtenez vraiment","valueItems":["Une présence qui inspire confiance au premier regard","Des demandes qui arrivent avec les bonnes informations","Tous les contacts et demandes au même endroit","Des relances envoyées au bon moment"],"howTitle":"Comment ça marche","howSteps":[{"title":"Demande","body":"Présentez votre activité dans un court formulaire."},{"title":"Appel","body":"Nous qualifions ensemble vos besoins."},{"title":"Création","body":"Nous concevons et configurons votre Studio ATS."},{"title":"Lancement","body":"Vous recevez des demandes structurées."}],"benefitsTitle":"Pourquoi c’est important pour votre activité","benefits":[{"title":"Confiance","body":"Les prospects vous vérifient en ligne avant d’appeler. Soignez cette première impression."},{"title":"Temps","body":"Connaissez budget, délai et type de projet avant de décrocher."},{"title":"Rien à gérer","body":"Conçu, hébergé et maintenu par l’équipe Studio ATS."}],"includedTitle":"Ce qui est inclus","whoTitle":"Pour qui","whoBody":"Les professionnels et entreprises dont chaque client compte, avec une offre visuelle ou premium et des demandes entrantes à convertir.","faqTitle":"Vos questions","offerTitle":"Une formule. Tout inclus.","offerNote":"Prix HT le cas échéant. Conditions définitives au contrat.","ctaTitle":"Prêt à parler de votre activité ?","ctaBody":"Laissez vos coordonnées — sans engagement. Nous revenons vers vous pour comprendre vos besoins."}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'page_variant', 'studio-default.artisans', 'en', 1, 'active', p.id, 'artisans', null, null, 'Artisans variant', null, '{"template":"studio-default","heroTitle":"Your work is excellent. Your online presence should be too.","heroSubtitle":"Prospects look you up before they call. Studio ATS gives your business a professional presence and collects complete requests — even while you’re on a job.","problemTitle":"Word of mouth isn’t enough anymore.","problemBody":"People who don’t know you yet check you online first. If they find little, they call someone else — and the requests that do arrive are scattered and incomplete.","ctaTitle":"Let’s look at your business together","ctaBody":"Leave your details and describe your trade in one line. No commitment."}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'page_variant', 'studio-default.artisans', 'fr', 1, 'active', p.id, 'artisans', null, null, 'Variante artisans', null, '{"template":"studio-default","heroTitle":"Votre travail est excellent. Votre présence en ligne doit l’être aussi.","heroSubtitle":"Les prospects vous cherchent avant d’appeler. Studio ATS donne à votre entreprise une présence professionnelle et recueille des demandes complètes — même pendant vos chantiers.","problemTitle":"Le bouche-à-oreille ne suffit plus.","problemBody":"Ceux qui ne vous connaissent pas encore vous vérifient d’abord en ligne. S’ils trouvent peu de choses, ils appellent quelqu’un d’autre — et les demandes qui arrivent sont éparpillées et incomplètes.","ctaTitle":"Regardons ensemble votre activité","ctaBody":"Laissez vos coordonnées et décrivez votre métier en une ligne. Sans engagement."}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'qualified-inquiries', 'en', 1, 'active', p.id, null, null, null, 'Generate more qualified inquiries', null, '{"promise":"Requests that arrive with budget, timing and details.","heroTitle":"Receive requests you can actually answer.","heroSubtitle":"Studio ATS asks the right questions before the first call, so every request arrives with the information you need."}'::jsonb, array[]::text[], 1, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'qualified-inquiries', 'fr', 1, 'active', p.id, null, null, null, 'Recevoir des demandes plus qualifiées', null, '{"promise":"Des demandes qui arrivent avec budget, délai et détails.","heroTitle":"Recevez des demandes auxquelles vous pouvez vraiment répondre.","heroSubtitle":"Studio ATS pose les bonnes questions avant le premier appel : chaque demande arrive avec les informations dont vous avez besoin."}'::jsonb, array[]::text[], 1, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'professional-presence', 'en', 1, 'active', p.id, null, null, null, 'Look as professional online as you are', null, '{"promise":"A presence that matches the quality of the work.","heroTitle":"Look as professional online as you are in real life.","heroSubtitle":"Prospects check you before they call. Give them a presence that inspires trust in seconds."}'::jsonb, array[]::text[], 2, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'professional-presence', 'fr', 1, 'active', p.id, null, null, null, 'Paraître aussi professionnel en ligne qu’en vrai', null, '{"promise":"Une présence à la hauteur de la qualité du travail.","heroTitle":"Soyez aussi professionnel en ligne que dans la réalité.","heroSubtitle":"Les prospects vous vérifient avant d’appeler. Offrez-leur une présence qui inspire confiance en quelques secondes."}'::jsonb, array[]::text[], 2, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'never-miss-request', 'en', 1, 'active', p.id, null, null, null, 'Stop losing requests', null, '{"promise":"Every request captured and centralised, even while busy.","heroTitle":"Stop losing requests while you work.","heroSubtitle":"Every request lands in one place with the right details — and follow-ups go out on time."}'::jsonb, array[]::text[], 3, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sales_angle', 'never-miss-request', 'fr', 1, 'active', p.id, null, null, null, 'Ne plus perdre de demandes', null, '{"promise":"Chaque demande captée et centralisée, même quand on est occupé.","heroTitle":"Ne perdez plus de demandes pendant que vous travaillez.","heroSubtitle":"Chaque demande arrive au même endroit avec les bons détails — et les relances partent au bon moment."}'::jsonb, array[]::text[], 3, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'playbook', 'generic', 'en', 1, 'active', p.id, null, null, null, 'Sell Studio ATS — the method', 'The 10 steps of a Studio ATS sale, for any target. Open a target to get its problems and angle injected.', '{"intro":"Sell the outcome, not the technology. Your job is to understand their situation, show them what they lose today, and send them the right page.","steps":[{"key":"understand","title":"Understand them","body":"Before contacting, look at how they present themselves online today and how a new client can reach them.","bullets":["Check their site, social profiles and reviews","Note one specific thing you like about their work"]},{"key":"opening","title":"Opening","body":"Start with them, not with Studio ATS. One genuine remark, one question.","bullets":["“I came across your work on …”","“Quick question: how do most new clients find you?”"]},{"key":"discovery","title":"Discovery","body":"Ask, then listen. Let them describe how requests arrive and what happens next.","bullets":["How do new clients contact you today?","What information is usually missing?","What happens when you can’t answer immediately?"]},{"key":"pain","title":"Identify the pain","body":"Name the problem with their words. Don’t invent one they don’t have."},{"key":"present","title":"Present Studio ATS","body":"Connect Studio ATS to the problem they just described — one sentence, not a feature list.","bullets":["“That’s exactly what Studio ATS handles: …”"]},{"key":"value","title":"Demonstrate value","body":"Talk about outcomes: trust, complete requests, time saved, nothing to manage. Never promise figures."},{"key":"objections","title":"Handle objections","body":"An objection is a question in disguise. Ask what’s behind it before answering."},{"key":"offer","title":"Send the offer","body":"Send your sales page for their sector: it explains everything and the price comes from Studio ATS."},{"key":"follow_up","title":"Follow up","body":"No reply after a few days? One short, useful follow-up — then respect their answer."},{"key":"close","title":"Close","body":"Agree on a clear next step: a call, a request on the page, or the purchase online."}]}'::jsonb, array['method', 'discovery', 'closing']::text[], 10, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'playbook', 'generic', 'fr', 1, 'active', p.id, null, null, null, 'Vendre Studio ATS — la méthode', 'Les 10 étapes d’une vente Studio ATS, pour toute cible. Ouvrez une cible pour y injecter ses problèmes et son angle.', '{"intro":"Vendez le résultat, pas la technologie. Votre rôle : comprendre leur situation, montrer ce qu’ils perdent aujourd’hui, et envoyer la bonne page.","steps":[{"key":"understand","title":"Les comprendre","body":"Avant de contacter, regardez comment ils se présentent en ligne et comment un nouveau client peut les joindre.","bullets":["Regardez leur site, leurs réseaux et leurs avis","Notez une chose précise que vous appréciez dans leur travail"]},{"key":"opening","title":"Ouverture","body":"Commencez par eux, pas par Studio ATS. Une remarque sincère, une question.","bullets":["« J’ai découvert votre travail sur … »","« Petite question : comment vos nouveaux clients vous trouvent-ils ? »"]},{"key":"discovery","title":"Découverte","body":"Questionnez, puis écoutez. Laissez-les décrire comment arrivent les demandes et ce qui se passe ensuite.","bullets":["Comment les nouveaux clients vous contactent-ils ?","Quelle information manque souvent ?","Que se passe-t-il quand vous ne pouvez pas répondre tout de suite ?"]},{"key":"pain","title":"Identifier le problème","body":"Nommez le problème avec leurs mots. N’inventez pas un problème qu’ils n’ont pas."},{"key":"present","title":"Présenter Studio ATS","body":"Reliez Studio ATS au problème qu’ils viennent de décrire — une phrase, pas une liste de fonctionnalités.","bullets":["« C’est exactement ce que Studio ATS prend en charge : … »"]},{"key":"value","title":"Montrer la valeur","body":"Parlez résultats : confiance, demandes complètes, temps gagné, rien à gérer. Ne promettez jamais de chiffres."},{"key":"objections","title":"Traiter les objections","body":"Une objection est une question déguisée. Demandez ce qu’il y a derrière avant de répondre."},{"key":"offer","title":"Envoyer l’offre","body":"Envoyez votre page commerciale pour leur secteur : elle explique tout et le prix vient de Studio ATS."},{"key":"follow_up","title":"Relancer","body":"Pas de réponse après quelques jours ? Une relance courte et utile — puis respectez leur réponse."},{"key":"close","title":"Conclure","body":"Convenez d’une prochaine étape claire : un appel, une demande sur la page, ou l’achat en ligne."}]}'::jsonb, array['méthode', 'découverte', 'closing']::text[], 10, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'playbook', 'artisans', 'en', 1, 'active', p.id, 'artisans', null, null, 'Sell Studio ATS to an artisan', 'Phone-first, short, concrete. Artisans are busy: respect their time.', '{"intro":"Artisans buy from people who understand their job. Talk about their clients and their time — never about “websites”.","steps":[{"key":"understand","title":"Understand them","body":"They are on site most of the day, get work through word of mouth, and answer calls between two jobs. Their reputation is their main asset.","bullets":["Look them up as a client would: what do you find?","Note their trade, area and the type of jobs they show"]},{"key":"opening","title":"Opening","body":"Call early morning or end of day. Be brief and specific.","bullets":["“I looked you up as a client would — can I share what I noticed? It takes 2 minutes.”"]},{"key":"discovery","title":"Discovery","body":"Three questions are enough.","bullets":["How do most of your new clients find you?","What happens when someone who doesn’t know you looks you up?","How many calls do you miss while you’re on a job?"]},{"key":"pain","title":"Identify the pain","body":"Usually: word of mouth has limits, the business looks less professional online than in reality, requests get lost."},{"key":"present","title":"Present Studio ATS","body":"“Studio ATS gives your business a professional presence that works while you’re on site: people see your work and send complete requests — job, place, timing.”"},{"key":"value","title":"Demonstrate value","body":"Trust from people who don’t know you yet. Requests you can answer in one go. Nothing to manage yourself."},{"key":"objections","title":"Handle objections","body":"Expect: “I already have social media”, “my clients come by word of mouth”, “I don’t have time”."},{"key":"offer","title":"Send the offer","body":"Send your artisan sales page by SMS or WhatsApp right after the call, while the conversation is fresh."},{"key":"follow_up","title":"Follow up","body":"Two to three days later, one short message: “Did you have time to look? Any question I can answer?”"},{"key":"close","title":"Close","body":"Propose the next step: a request on the page, a call with the Studio ATS team, or the purchase online when available."}]}'::jsonb, array['artisan', 'phone', 'word of mouth', 'social media']::text[], 11, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'playbook', 'artisans', 'fr', 1, 'active', p.id, 'artisans', null, null, 'Vendre Studio ATS à un artisan', 'Téléphone d’abord, court, concret. Les artisans sont occupés : respectez leur temps.', '{"intro":"Les artisans achètent à ceux qui comprennent leur métier. Parlez de leurs clients et de leur temps — jamais de « site internet ».","steps":[{"key":"understand","title":"Les comprendre","body":"Ils sont sur les chantiers la plupart de la journée, travaillent par bouche-à-oreille et répondent entre deux interventions. Leur réputation est leur principal atout.","bullets":["Cherchez-les comme le ferait un client : que trouvez-vous ?","Notez leur métier, leur zone et les travaux qu’ils montrent"]},{"key":"opening","title":"Ouverture","body":"Appelez tôt le matin ou en fin de journée. Soyez bref et précis.","bullets":["« Je vous ai cherché comme le ferait un client — je peux vous dire ce que j’ai remarqué ? Ça prend 2 minutes. »"]},{"key":"discovery","title":"Découverte","body":"Trois questions suffisent.","bullets":["Comment la plupart de vos nouveaux clients vous trouvent-ils ?","Que se passe-t-il quand quelqu’un qui ne vous connaît pas vous cherche ?","Combien d’appels manquez-vous pendant un chantier ?"]},{"key":"pain","title":"Identifier le problème","body":"En général : le bouche-à-oreille a ses limites, l’entreprise paraît moins professionnelle en ligne qu’en vrai, des demandes se perdent."},{"key":"present","title":"Présenter Studio ATS","body":"« Studio ATS donne à votre entreprise une présence professionnelle qui travaille pendant vos chantiers : on voit vos réalisations et on vous envoie des demandes complètes — travaux, lieu, délai. »"},{"key":"value","title":"Montrer la valeur","body":"La confiance de ceux qui ne vous connaissent pas encore. Des demandes auxquelles on répond en une fois. Rien à gérer soi-même."},{"key":"objections","title":"Traiter les objections","body":"Attendez-vous à : « j’ai déjà les réseaux sociaux », « mes clients viennent par le bouche-à-oreille », « je n’ai pas le temps »."},{"key":"offer","title":"Envoyer l’offre","body":"Envoyez votre page artisans par SMS ou WhatsApp juste après l’appel, tant que l’échange est frais."},{"key":"follow_up","title":"Relancer","body":"Deux à trois jours plus tard, un message court : « Vous avez eu le temps de regarder ? Une question ? »"},{"key":"close","title":"Conclure","body":"Proposez la prochaine étape : une demande sur la page, un appel avec l’équipe Studio ATS, ou l’achat en ligne quand il est disponible."}]}'::jsonb, array['artisan', 'téléphone', 'bouche-à-oreille', 'réseaux sociaux']::text[], 11, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'discovery-call', 'en', 1, 'active', p.id, null, 'phone', null, 'Discovery call (any target)', '5 minutes to understand, qualify and agree on a next step.', '{"intro":"Tick each step as you go. Talk less than them.","steps":[{"type":"opening","text":"Hello {{firstName}}, it’s {{advisorName}}. I’m calling about how new clients reach {{company}} — do you have 2 minutes?"},{"type":"question","text":"How do most of your new clients find you today?"},{"type":"listen","text":"Word of mouth only? Social media? Requests by phone during work?","hint":"Write down their exact words."},{"type":"question","text":"What happens when someone who doesn’t know you looks you up online?"},{"type":"problem","text":"They find little, or requests arrive scattered and incomplete."},{"type":"response","text":"That’s what Studio ATS handles: a professional presence that inspires trust and collects complete requests — built and maintained for you."},{"type":"objection","text":"“I already have social media.”"},{"type":"answer","text":"Social media shows your work. Studio ATS turns the interest into a complete request. Where do people send you a request today?"},{"type":"cta","text":"Can I send you the page for your sector? It explains everything, including the price, in 3 minutes."}]}'::jsonb, array['phone', 'discovery', 'call']::text[], 20, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'discovery-call', 'fr', 1, 'active', p.id, null, 'phone', null, 'Appel découverte (toute cible)', '5 minutes pour comprendre, qualifier et convenir d’une prochaine étape.', '{"intro":"Cochez chaque étape au fil de l’appel. Parlez moins qu’eux.","steps":[{"type":"opening","text":"Bonjour {{firstName}}, c’est {{advisorName}}. Je vous appelle au sujet de la façon dont les nouveaux clients contactent {{company}} — vous avez 2 minutes ?"},{"type":"question","text":"Comment la plupart de vos nouveaux clients vous trouvent-ils aujourd’hui ?"},{"type":"listen","text":"Uniquement le bouche-à-oreille ? Les réseaux ? Des appels pendant le travail ?","hint":"Notez leurs mots exacts."},{"type":"question","text":"Que se passe-t-il quand quelqu’un qui ne vous connaît pas vous cherche en ligne ?"},{"type":"problem","text":"Il trouve peu de choses, ou les demandes arrivent éparpillées et incomplètes."},{"type":"response","text":"C’est ce que Studio ATS prend en charge : une présence professionnelle qui inspire confiance et recueille des demandes complètes — conçue et maintenue pour vous."},{"type":"objection","text":"« J’ai déjà les réseaux sociaux. »"},{"type":"answer","text":"Les réseaux montrent votre travail. Studio ATS transforme l’intérêt en demande complète. Aujourd’hui, où les gens vous envoient-ils une demande ?"},{"type":"cta","text":"Je peux vous envoyer la page de votre secteur ? Elle explique tout, prix compris, en 3 minutes."}]}'::jsonb, array['téléphone', 'découverte', 'appel']::text[], 20, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'artisans-phone', 'en', 1, 'active', p.id, 'artisans', 'phone', null, 'Artisan — first call', 'Short call between two jobs.', '{"steps":[{"type":"opening","text":"Hello {{firstName}}, {{advisorName}} here. I looked up {{company}} as a client would — can I tell you what I noticed? Two minutes."},{"type":"question","text":"Most of your work comes through word of mouth, right?"},{"type":"listen","text":"Pride in their reputation; maybe quieter periods; missed calls on site."},{"type":"question","text":"And when a friend recommends you, what does that person find when they look you up?"},{"type":"problem","text":"Little or nothing that reflects the quality of the work — some people call someone else."},{"type":"response","text":"Studio ATS gives you a professional presence that works while you’re on site: people see your work and send you complete requests."},{"type":"objection","text":"“I don’t have time for that.”"},{"type":"answer","text":"That’s the point: the Studio ATS team builds and maintains it. You just receive the requests."},{"type":"cta","text":"I’ll text you the page for artisans — have a look tonight, and I’ll call you back Thursday?"}]}'::jsonb, array['artisan', 'phone', 'word of mouth']::text[], 21, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'artisans-phone', 'fr', 1, 'active', p.id, 'artisans', 'phone', null, 'Artisan — premier appel', 'Appel court entre deux chantiers.', '{"steps":[{"type":"opening","text":"Bonjour {{firstName}}, {{advisorName}} à l’appareil. J’ai cherché {{company}} comme le ferait un client — je peux vous dire ce que j’ai remarqué ? Deux minutes."},{"type":"question","text":"L’essentiel de votre travail vient du bouche-à-oreille, c’est bien ça ?"},{"type":"listen","text":"Fierté de leur réputation ; périodes plus calmes ; appels manqués sur les chantiers."},{"type":"question","text":"Et quand un ami vous recommande, que trouve cette personne quand elle vous cherche ?"},{"type":"problem","text":"Peu ou rien qui reflète la qualité du travail — certains appellent quelqu’un d’autre."},{"type":"response","text":"Studio ATS vous donne une présence professionnelle qui travaille pendant vos chantiers : on voit vos réalisations et on vous envoie des demandes complètes."},{"type":"objection","text":"« Je n’ai pas le temps pour ça. »"},{"type":"answer","text":"Justement : l’équipe Studio ATS le conçoit et le maintient. Vous recevez simplement les demandes."},{"type":"cta","text":"Je vous envoie par SMS la page pour les artisans — regardez ce soir, et je vous rappelle jeudi ?"}]}'::jsonb, array['artisan', 'téléphone', 'bouche-à-oreille']::text[], 21, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-whatsapp', 'en', 1, 'active', p.id, null, 'whatsapp', 'first_contact', 'First contact — short message', null, '{"text":"Hello {{firstName}}, I came across {{company}} and liked your work. Quick question: how do most new clients reach you today? I work with Studio ATS, which helps professionals turn online interest into complete requests. Here’s a 3-minute overview for your sector: {{affiliateUrl}}"}'::jsonb, array[]::text[], 30, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-whatsapp', 'fr', 1, 'active', p.id, null, 'whatsapp', 'first_contact', 'Premier contact — message court', null, '{"text":"Bonjour {{firstName}}, j’ai découvert {{company}} et j’ai aimé votre travail. Petite question : comment vos nouveaux clients vous contactent-ils aujourd’hui ? Je travaille avec Studio ATS, qui aide les professionnels à transformer l’intérêt en ligne en demandes complètes. Voici un aperçu de 3 minutes pour votre secteur : {{affiliateUrl}}"}'::jsonb, array[]::text[], 30, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-linkedin', 'en', 1, 'active', p.id, null, 'linkedin', 'first_contact', 'First contact — LinkedIn', null, '{"text":"Hi {{firstName}}, I enjoy what you share about {{sector}}. When someone is interested in working with {{company}}, where do you send them? I help professionals set up Studio ATS, a space that presents their work and qualifies each request. Open to a quick look?"}'::jsonb, array[]::text[], 31, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-linkedin', 'fr', 1, 'active', p.id, null, 'linkedin', 'first_contact', 'Premier contact — LinkedIn', null, '{"text":"Bonjour {{firstName}}, j’apprécie ce que vous partagez sur {{sector}}. Quand quelqu’un souhaite travailler avec {{company}}, où l’envoyez-vous ? J’accompagne des professionnels sur Studio ATS, un espace qui présente leur travail et qualifie chaque demande. Partant pour un rapide coup d’œil ?"}'::jsonb, array[]::text[], 31, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
