insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'after-call-recap', 'en', 1, 'active', p.id, null, 'whatsapp', 'after_call', 'After the call — recap', null, '{"text":"Thanks {{firstName}} for your time. To sum up: you’d like requests that arrive complete and a presence that reflects {{company}}. Everything is explained here, price included: {{affiliateUrl}}. Next step as agreed: {{campaign}}."}'::jsonb, array[]::text[], 36, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'after-call-recap', 'fr', 1, 'active', p.id, null, 'whatsapp', 'after_call', 'Après l’appel — récapitulatif', null, '{"text":"Merci {{firstName}} pour votre temps. En résumé : vous souhaitez des demandes qui arrivent complètes et une présence à l’image de {{company}}. Tout est expliqué ici, prix compris : {{affiliateUrl}}. Prochaine étape comme convenu : {{campaign}}."}'::jsonb, array[]::text[], 36, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'interested-book', 'en', 1, 'active', p.id, null, 'other', 'interested', 'Interested — book the next step', null, '{"text":"Great, {{firstName}}! The simplest next step: leave your request on this page so the Studio ATS team can prepare the call: {{affiliateUrl}}. Which day suits you?"}'::jsonb, array[]::text[], 37, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
