insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'objection-social', 'en', 1, 'active', p.id, null, 'other', 'objection', 'Objection — “I already have social media”', null, '{"text":"I understand, {{firstName}} — your social media shows your work well. Studio ATS doesn’t replace it: it turns that interest into complete requests, in one place you control. Where do people send you a request today?"}'::jsonb, array['instagram', 'facebook', 'réseaux sociaux', 'social media']::text[], 39, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'objection-social', 'fr', 1, 'active', p.id, null, 'other', 'objection', 'Objection — « J’ai déjà les réseaux sociaux »', null, '{"text":"Je comprends, {{firstName}} — vos réseaux montrent bien votre travail. Studio ATS ne les remplace pas : il transforme cet intérêt en demandes complètes, dans un espace que vous maîtrisez. Aujourd’hui, où vous envoie-t-on une demande ?"}'::jsonb, array['instagram', 'facebook', 'réseaux sociaux', 'social media']::text[], 39, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
